// iva: HTTP servers on the panel's own TCP systems (<HttpServer>, the web
// server of <WebApp> and the ColorPicker's swatch). Generated by iva.
//
// A TCP system accepting connections, its feedback "request" matching a
// request's head, is an HTTP server: CommandFusion's DynamicHTML demo does
// the same. iViewer sends what CF.send writes to every client the system has
// - a page can receive the answer meant for another. So iva's web server
// (one port for every web app) answers everything with the same page, the
// boot page, the answer's data in it: whatever a web view gets is a page that
// knows from its own URL what to show, and a request of iva/web checks that
// the answer is its own (the number it sent) and asks again if not. Each
// answer closes its connection (Connection: close).
var IvaHttp = (() => {
  const REASONS = { 200: 'OK', 204: 'No Content', 400: 'Bad Request', 404: 'Not Found', 500: 'Internal Server Error' };
  const TYPES = {
    html: 'text/html; charset=utf-8', js: 'text/javascript; charset=utf-8', css: 'text/css; charset=utf-8',
    json: 'application/json; charset=utf-8', txt: 'text/plain; charset=utf-8', svg: 'image/svg+xml',
    png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', gif: 'image/gif', webp: 'image/webp',
    glb: 'model/gltf-binary', gltf: 'model/gltf+json', bin: 'application/octet-stream', wasm: 'application/wasm',
    mp3: 'audio/mpeg', wav: 'audio/wav', ttf: 'font/ttf', otf: 'font/otf', woff: 'font/woff', woff2: 'font/woff2',
  };

  const decode = (s) => {
    try {
      return decodeURIComponent(s.replace(/\+/g, ' '));
    } catch {
      return s;
    }
  };

  /** A request's head: method, path, query (decoded), headers (lower case names). */
  function parse(raw) {
    const lines = String(raw).replace(/^[\r\n]+/, '').split('\r\n');
    const m = /^([A-Za-z]+) ([^ ]+)/.exec(lines[0] || '');
    if (!m) return null;
    const target = m[2];
    const q = target.indexOf('?');
    const query = {};
    const headers = {};
    if (q >= 0) {
      for (const pair of target.slice(q + 1).split('&')) {
        if (!pair) continue;
        const e = pair.indexOf('=');
        query[decode(e < 0 ? pair : pair.slice(0, e))] = e < 0 ? '' : decode(pair.slice(e + 1));
      }
    }
    for (const line of lines.slice(1)) {
      const h = /^([^:]+):\s*(.*)$/.exec(line);
      if (h) headers[h[1].toLowerCase()] = h[2];
    }
    return { method: m[1].toUpperCase(), path: decode(q < 0 ? target : target.slice(0, q)), query, headers };
  }

  /** Text as UTF-8 bytes, a char per byte: what CF.send sends as it is. */
  const utf8 = (s) => unescape(encodeURIComponent(s));
  /** JSON that can go in a page's <script>: ASCII only, no "</". */
  const scriptJson = (v) => JSON.stringify(v === undefined ? null : v)
    .replace(/[\u007f-￿]/g, (c) => `\\u${c.charCodeAt(0).toString(16).padStart(4, '0')}`)
    .replace(/</g, '\\u003c');
  const typeOf = (name) => {
    const m = /\.(\w+)$/.exec(name);
    return (m && TYPES[m[1].toLowerCase()]) || 'application/octet-stream';
  };

  /**
   * The boot page's script (its source goes in the page). It runs in the web
   * view: a swatch (/iva-color/RRGGBB) shows its colour; a web app (/<name>/)
   * asks for its settings and script (iva/boot, checked, asked again until
   * it's its own) and runs it.
   */
  function boot() {
    if (window.__ivaBoot) return;
    window.__ivaBoot = true;
    // iViewer's web views (Android) lay a page out as tall as nothing: height: 100% (html, body)
    // comes out 0 - the window's height in pixels instead, now and on every resize
    function fit(all) {
      var h = innerHeight + 'px';
      document.documentElement.style.height = h;
      if (all && document.body) document.body.style.height = h;
    }
    function fitting(all) {
      fit(all);
      addEventListener('resize', function () { fit(all); });
      if (!document.body) document.addEventListener('DOMContentLoaded', function () { fit(all); });
    }
    var swatch = /\/iva-color\/([0-9a-f]{6})\/?$/i.exec(location.pathname);
    if (swatch) {
      var style = document.createElement('style');
      style.textContent = 'html,body{background:#' + swatch[1] + '!important}';
      document.head.appendChild(style);
      return;
    }
    // what a page meets on the panel - its size, its errors - in the panel's log (iva serve shows it)
    function report(m) {
      try {
        var x = new XMLHttpRequest();
        x.open('GET', '/iva/log?m=' + encodeURIComponent(location.pathname + ': ' + m));
        x.send();
      } catch (e) {}
    }
    window.addEventListener('error', function (e) { report('error: ' + e.message + (e.filename ? ' (' + e.filename + ':' + e.lineno + ')' : '')); });
    window.addEventListener('unhandledrejection', function (e) { report('error: ' + (e.reason && e.reason.message || e.reason)); });
    // a canvas whose GPU went (a WebGL crash takes every web view's canvas with it): said, once each
    window.addEventListener('webglcontextlost', function () { report('a WebGL context was lost'); }, true);
    // what the page says is wrong (three.js: a shader that doesn't compile), the first few
    var said = 0;
    var cerror = console.error;
    console.error = function () {
      if (said++ < 5) report('console.error: ' + Array.prototype.map.call(arguments, String).join(' ').slice(0, 300));
      return cerror.apply(console, arguments);
    };
    function size() {
      return innerWidth + 'x' + innerHeight + ' dpr ' + devicePixelRatio + ', html ' + Math.round(document.documentElement.getBoundingClientRect().height) + 'px' +
        (document.hidden ? ', hidden' : '');
    }
    report('loaded, ' + size());
    setTimeout(function () { report('after 3 s, ' + size()); }, 3000);
    var name = location.pathname.replace(/\/+$/, '').split('/').pop();
    var tries = 0;
    // a page of the project (/iva-file/page.html): its HTML in the data, written over this page
    var file = /\/iva-file\/(.+)$/.exec(location.pathname);
    var path = file ? decodeURIComponent(file[1]) : '';
    function show(data) {
      if (data.error) {
        document.body.textContent = data.error;
        return;
      }
      document.open();
      document.write(data.file);
      document.close();
      // the page's own height: its html as tall as the window (its body as it says)
      fitting(false);
      // how it's laid out where it is (the window, its timers stay)
      setTimeout(function () {
        var b = document.body, first = b && b.firstElementChild, r = first && first.getBoundingClientRect();
        report('shown, ' + document.compatMode + ', body ' + (b ? getComputedStyle(b).display + ' ' + Math.round(b.getBoundingClientRect().height) + 'px' : 'none') +
          (r ? ', first element at ' + Math.round(r.top) + ' (' + Math.round(r.height) + 'px)' : '') + ', ' + size());
      }, 1000);
    }
    // the data is after this script, in the page's last script
    function unwrap(text) {
      var at = text.lastIndexOf('id="iva-data">');
      if (at < 0) return null;
      try {
        return JSON.parse(text.slice(at + 14, text.lastIndexOf('<\/script>')));
      } catch (e) {
        return null;
      }
    }
    function ask() {
      var r = Math.random().toString(36).slice(2, 10);
      var x = new XMLHttpRequest();
      if (file) {
        // the page again, numbered: until the answer is its own
        x.open('GET', location.pathname + '?r=' + r);
        x.timeout = 30000;
        x.onload = function () {
          var data = x.getResponseHeader('X-Iva-Req') === r ? unwrap(x.responseText) : null;
          if (data && data.path === path) return show(data);
          setTimeout(ask, Math.min(3000, 30 * ++tries));
        };
        x.onerror = x.ontimeout = function () { setTimeout(ask, Math.min(5000, 250 * ++tries)); };
        x.send();
        return;
      }
      x.open('GET', 'iva/boot?r=' + r);
      x.timeout = 30000;
      x.onload = function () {
        var data = x.getResponseHeader('X-Iva-Req') === r ? unwrap(x.responseText) : null;
        if (data && data.error) {
          document.body.textContent = data.error;
          return;
        }
        if (!data || !data.code) return setTimeout(ask, Math.min(3000, 30 * ++tries));
        window.__iva = data;
        if (data.bg) document.body.style.background = data.bg;
        var s = document.createElement('script');
        s.text = data.code;
        document.body.appendChild(s);
      };
      x.onerror = x.ontimeout = function () { setTimeout(ask, Math.min(5000, 250 * ++tries)); };
      x.send();
    }
    function start() {
      // this page (an app's): html and body as tall as the window
      fitting(true);
      // the page's own data, when this answer is its own: the app's colour while it loads
      var own = null;
      try {
        own = JSON.parse(document.getElementById('iva-data').textContent);
      } catch (e) {
        own = null;
      }
      if (file && own && own.path === path) return show(own);
      if (own && own.app === name && own.bg) document.body.style.background = own.bg;
      ask();
    }
    if (document.body) start();
    else document.addEventListener('DOMContentLoaded', start);
  }
  const BOOT = `(${String(boot)})();`;

  /** The boot page with data in it (JSON, made safe for a page): every answer of the web server. */
  const pageWith = (json) => '<!DOCTYPE html><html><head><meta charset="utf-8">' +
    '<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no">' +
    '<style>html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#000;-webkit-user-select:none;user-select:none;' +
    '-webkit-tap-highlight-color:transparent;-webkit-touch-callout:none}</style>' +
    `<script>${BOOT}</script></head><body><script type="application/json" id="iva-data">${json}</script></body></html>`;
  const page = (data) => pageWith(scriptJson(data));

  /** What a handler answers with: res.json / html / text / bytes / asset / page, once. */
  function response(system, req) {
    let done = false;
    const res = {
      sent: () => done,
      bytes(type, bytes, status = 200, headers = {}) {
        if (done) return;
        done = true;
        let head = `HTTP/1.1 ${status} ${REASONS[status] || 'OK'}\r\nContent-Type: ${type}\r\nContent-Length: ${bytes.length}\r\n` +
          'Cache-Control: no-store\r\nConnection: close\r\nAccess-Control-Allow-Origin: *\r\n';
        // the request's number back: the page tells its own answer from another's
        if (req.query.r !== undefined) head += `X-Iva-Req: ${String(req.query.r).replace(/[^\w.-]/g, '')}\r\n`;
        for (const [k, v] of Object.entries(headers)) head += `${k}: ${v}\r\n`;
        CF.send(system, `${head}\r\n${bytes}`, CF.BINARY);
      },
      text: (s, status) => res.bytes(TYPES.txt, utf8(String(s)), status),
      html: (s, status) => res.bytes(TYPES.html, utf8(String(s)), status),
      json: (v, status) => res.bytes(TYPES.json, utf8(JSON.stringify(v === undefined ? null : v)), status),
      /** the boot page with `data` in it (the web server answers only so) */
      page: (data, status) => res.bytes(TYPES.html, page(data), status),
      /** a file of the project (CF.loadAsset): images, models, data */
      asset(name, type) {
        CF.loadAsset(name, CF.BINARY, (data) => {
          if (data === null || data === undefined) res.text(`not found: ${name}`, 404);
          else res.bytes(type || typeOf(name), data);
        });
      },
      notFound: () => res.text(`not found: ${req.path}`, 404),
    };
    return res;
  }

  /**
   * An HTTP server on a TCP system accepting connections (its feedback
   * "request": (?msi)^.*?\r\n\r\n). handler(req, res): req.method, path,
   * query, headers; answer with res.json(v), res.html(s), res.text(s, status),
   * res.bytes(type, bytes), res.asset(name) - now or later. One client at a
   * time gets its own answer (see above).
   */
  function serve(system, handler) {
    CF.watch(CF.FeedbackMatchedEvent, system, 'request', (fb, raw) => {
      const req = parse(raw);
      if (!req) return;
      const res = response(system, req);
      try {
        handler(req, res);
      } catch (e) {
        CF.log(`IvaHttp ${system}: ${e}`);
        res.text(`error: ${e}`, 500);
      }
    });
  }

  // ── the web server: web apps (/<name>/) and swatches (/iva-color/RRGGBB), one port ──

  let web = null;
  // the server answers (its self-check passed): the web views get their URLs, what waited runs
  let up = false;
  const views = [];
  const waiting = [];
  const apps = {};
  // the apps' scripts, read once, as JSON
  const kept = {};

  const numberOf = (v) => {
    const n = typeof v === 'number' ? v : parseFloat(v);
    return Number.isNaN(n) ? null : n;
  };
  const globalFn = (name) => {
    if (typeof name === 'function') return name;
    try {
      return (0, eval)(name);
    } catch {
      return null;
    }
  };
  // the app's options and colour in the look shown (<Project themes>: each look has its own)
  const lookOf = (a) => (typeof IvaTheme !== 'undefined' && IvaTheme.app && IvaTheme.app(a.name)) || { options: a.o.options || {}, bg: a.o.bg };

  function changed(a) {
    a.version++;
    if (a.flush) return;
    // changes close together go in one answer
    a.flush = setTimeout(() => {
      a.flush = null;
      // held for news: nothing newer than what that page has, still held
      if (!a.held || a.held.since === a.version) return;
      const { res, timer } = a.held;
      a.held = null;
      clearTimeout(timer);
      answer(a, res);
    }, 20);
  }

  function answer(a, res) {
    const out = { v: a.version, values: a.values };
    if (a.reload) out.reload = a.reload;
    if (a.samples) out.sample = a.samples.length ? a.samples[a.samples.length - 1] : null;
    res.page(out);
  }

  /** iva/boot: the app's settings and its script (kept, as JSON: put in the answer as it is) */
  function bootApp(a, res) {
    const send = (code) => {
      const look = lookOf(a);
      const rest = scriptJson({ names: a.names, options: look.options, values: a.values, v: a.version, reload: a.reload, record: a.samples ? a.recordNames : null, bg: look.bg });
      res.bytes(TYPES.html, pageWith(`{"code":${code},${rest.slice(1)}`));
    };
    if (kept[a.o.asset] !== undefined) return send(kept[a.o.asset]);
    CF.loadAsset(a.o.asset, CF.UTF8, (code) => {
      if (code === null || code === undefined) return res.page({ error: `iva: ${a.o.asset} is missing from the project` }, 500);
      kept[a.o.asset] = scriptJson(code);
      send(kept[a.o.asset]);
    });
  }

  function call(a, req, res) {
    const name = req.query.fn;
    // IvaHttp.handle's, then the WebApp's handlers, then iva's own (history with record)
    const fn = a.handlers[name] || globalFn(a.o.handlers && a.o.handlers[name]) || a.builtins[name];
    if (!fn) return res.page({ error: `no handler "${name}"` }, 404);
    let args;
    try {
      args = JSON.parse(req.query.args || '[]');
    } catch (e) {
      return res.page({ error: `args: ${e}` }, 400);
    }
    let replied = false;
    const reply = (v) => {
      if (replied) return;
      replied = true;
      res.page({ value: v === undefined ? null : v });
    };
    try {
      const out = fn(...args, reply);
      if (out !== undefined) reply(out);
    } catch (e) {
      replied = true;
      res.page({ error: String(e) }, 500);
    }
  }

  function route(a, p, req, res) {
    // a new request of this app: its page gave up the one held (it asks one thing at a time)
    if (a.held) {
      clearTimeout(a.held.timer);
      a.held = null;
    }
    if (p === '/' || p === '/index.html') return res.page({ app: a.name, bg: lookOf(a).bg });
    if (p === '/iva/boot') return bootApp(a, res);
    if (p === '/iva/poll') {
      if (Number(req.query.v) !== a.version) return answer(a, res);
      // nothing new: held until something changes (or a while passes)
      const timer = setTimeout(() => {
        if (a.held && a.held.res === res) {
          a.held = null;
          answer(a, res);
        }
      }, 20000);
      a.held = { res, timer, since: a.version };
      return;
    }
    if (p === '/iva/set') {
      for (const [k, v] of Object.entries(req.query)) if (k !== 'r' && a.o.joins[k] !== undefined) CF.setJoin(a.o.joins[k], v);
      return res.page({ ok: 1 });
    }
    if (p === '/iva/call') return call(a, req, res);
    if (p.startsWith('/iva/asset/')) {
      const name = p.slice('/iva/asset/'.length);
      CF.loadAsset(name, CF.BINARY, (data) => {
        if (data === null || data === undefined) res.page({ error: `not found: ${name}` }, 404);
        else res.page({ type: typeOf(name), b64: btoa(data) });
      });
      return;
    }
    res.page({ error: `not found: ${p}` }, 404);
  }

  /** The web server, on its TCP system: the first part of a path names the web app. */
  function webServe(req, res) {
    // the server's self-check (IvaHttp.web); what a page reports (its size, its errors): the panel's log
    if (req.path === '/iva/ping') return res.text('ok');
    if (req.path === '/iva/log') {
      CF.log(`web ${String(req.query.m || '').slice(0, 500)}`);
      return res.text('ok');
    }
    const parts = req.path.replace(/^\/+/, '').split('/');
    // a swatch: the boot page shows the colour its URL names
    if (parts[0] === 'iva-color') return res.page(null);
    // a page of the project (a file of its image folder, CF.loadAsset): the boot page writes it in
    if (parts[0] === 'iva-file') {
      const name = parts.slice(1).map((x) => decodeURIComponent(x)).join('/');
      CF.loadAsset(name, CF.UTF8, (text) => {
        if (text === null || text === undefined) res.page({ path: name, error: `not found: ${name}` }, 404);
        else res.page({ path: name, file: String(text) });
      });
      return;
    }
    const a = apps[parts[0]];
    if (!a) return res.page({ error: `no web app "${parts[0]}"` }, 404);
    route(a, `/${parts.slice(1).join('/')}`, req, res);
  }

  /**
   * A web app (<WebApp>), at /<name>/ on the web server: its page boots it
   * (iva/boot: its settings, its script); iva/poll answers with the joins'
   * values when they change; iva/set sets joins; iva/call runs a panel
   * function; iva/asset/<name> sends a project file.
   */
  function app(name, o) {
    const a = apps[name] = { name, o, names: Object.keys(o.joins || {}), values: {}, version: 1, held: null, flush: null, handlers: {}, builtins: {}, reload: 0 };
    for (const key of a.names) {
      const join = o.joins[key];
      const serial = String(join).charAt(0) === 's';
      CF.watch(CF.JoinChangeEvent, join, (j, v) => {
        const value = serial ? String(v ?? '') : Number(v) || 0;
        if (a.values[key] === value) return;
        a.values[key] = value;
        changed(a);
      }, true);
    }
    if (o.record) record(a, o.record);
  }

  /** The numbers among the joins, every so often: the app's history (panel.history). */
  function record(a, r) {
    const names = r.names || a.names;
    const keep = r.keep || 3600;
    a.recordNames = names;
    a.samples = [];
    const take = () => {
      a.samples.push([Date.now(), ...names.map((n) => numberOf(a.values[n]))]);
      if (a.samples.length > keep) a.samples.splice(0, a.samples.length - keep);
      changed(a);
    };
    take();
    setInterval(take, Math.max(0.2, r.every || 1) * 1000);
    a.builtins.history = (from, to) => ({
      names,
      rows: a.samples.filter(([t]) => (from == null || t >= from) && (to == null || t <= to)),
    });
  }

  /** after a look switch: each app's page again, in the new look's settings */
  function themeChanged() {
    for (const a of Object.values(apps)) {
      a.reload++;
      changed(a);
    }
  }
  CF.modules.push({ name: 'iva-http', setup() {
    if (typeof IvaTheme !== 'undefined' && IvaTheme.onChange) IvaTheme.onChange(themeChanged);
  } });

  /** the server answers: the web views load (their URLs set now - before, they'd show "failed"), then what waited */
  function answered() {
    if (up) return;
    up = true;
    for (const v of views) CF.setJoin(v.join, url(v.path));
    for (const fn of waiting.splice(0)) {
      try {
        fn();
      } catch (e) {
        CF.log(`IvaHttp: ${e}`);
      }
    }
  }

  /**
   * Asks the server itself until it answers. iViewer starts it a while after
   * the page shows - on Android only once it's switched off and on (iva does
   * so at start): not answering, it's switched off and on again now and then.
   * A request iViewer leaves hanging doesn't hold the next one up.
   */
  function check(system, port) {
    const at = [300, 700, 1200, 2000, 3000, 4500, 6500, 9000, 12000, 16000, 21000, 27000, 35000, 45000, 60000];
    const restartAt = new Set([1500, 5000, 13000, 30000]);
    const t0 = Date.now();
    let n = 0;
    const ask = () => {
      if (up) return;
      CF.request(`http://127.0.0.1:${port}/iva/ping?n=${++n}`, (status) => {
        if (status === 200) answered();
      });
    };
    for (const ms of at) setTimeout(ask, ms);
    for (const ms of restartAt) {
      setTimeout(() => {
        if (up) return;
        CF.log(`IvaHttp: the web server (${system}, port ${port}) doesn't answer after ${Math.round((Date.now() - t0) / 1000)} s - switching it off and on`);
        CF.setSystemProperties(system, { enabled: false });
        setTimeout(() => CF.setSystemProperties(system, { enabled: true }), 300);
      }, ms);
    }
  }

  const url = (path) => `http://127.0.0.1:${web ? web.port : 0}/${String(path).replace(/^\/+/, '')}`;

  return {
    serve,
    /** the web server on its system and port (iva sets it up); it checks itself */
    web(system, port) {
      if (web) return;
      web = { system, port };
      serve(system, webServe);
      check(system, port);
    },
    /** a web view on the web server: its URL join set to the page at `path` once the server answers */
    view(join, path) {
      if (views.some((v) => v.join === join)) return;
      views.push({ join, path });
      if (up) CF.setJoin(join, url(path));
    },
    /** fn() once the server answers (now, if it does): before, a web view would show "failed" */
    ready(fn) {
      if (up) fn();
      else waiting.push(fn);
    },
    /** a page of the web server: http://127.0.0.1:<port>/<path> */
    url,
    app,
    /** a function a web app can call (panel.call(name, ...args)): fn(...args, reply) returns the answer or replies later */
    handle(name, fnName, fn) {
      if (apps[name]) apps[name].handlers[fnName] = fn;
    },
    utf8,
    parse,
  };
})();
